 s+=par(0,'var(--bad)',1.6,null,'экватор')+par(23.44,'var(--accent-ink)',1,'4 3','тропик')+par(-23.44,'var(--accent-ink)',1,'4 3','')+par(66.56,'var(--accent-ink)',1,'2 3','пол. круг')+par(-66.56,'var(--accent-ink)',1,'2 3','');
 s+=LN(cx-ax[0]*(R+18),cy-ax[1]*(R+18),cx+ax[0]*(R+18),cy+ax[1]*(R+18),{sw:2});s+=TX(cx+ax[0]*(R+28),cy+ax[1]*(R+28)+4,'С',{fs:12,c:'var(--bad)'})+TX(cx-ax[0]*(R+28),cy-ax[1]*(R+28)+4,'Ю',{fs:12});
 if(phi!=null){const [a,b]=P(phi);/* split at x=cx */const tt=(cx-a[0])/((b[0]-a[0])||1e-9);let m=[a[0]+(b[0]-a[0])*Math.max(0,Math.min(1,tt)),a[1]+(b[1]-a[1])*Math.max(0,Math.min(1,tt))];
  s+=LN(a[0],a[1],m[0],m[1],{c:'var(--hl)',sw:5})+LN(m[0],m[1],b[0],b[1],{c:'var(--ink)',sw:5,op:0.7});}
