const figBelts=(()=>{let s='';const cx=96,cy=110,R=88;const Y=l=>cy-R*Math.sin(l*Math.PI/180);
 const band=(l1,l2,c,o)=>{const a1=Math.asin(Math.sin(l1*Math.PI/180)),a2=Math.asin(Math.sin(l2*Math.PI/180));const x1=R*Math.cos(a1),x2=R*Math.cos(a2);return PATH(`M${cx-x1},${Y(l1)} L${cx+x1},${Y(l1)} A${R},${R} 0 0 ${l2>l1?0:1} ${cx+x2},${Y(l2)} L${cx-x2},${Y(l2)} A${R},${R} 0 0 ${l2>l1?0:1} ${cx-x1},${Y(l1)} Z`,{f:c,fo:o});};
 s+=band(-23.44,23.44,'var(--bad)',0.35)+band(23.44,66.56,'var(--ok)',0.35)+band(-66.56,-23.44,'var(--ok)',0.35)+band(66.56,90,'var(--accent)',0.35)+band(-90,-66.56,'var(--accent)',0.35)+CIR(cx,cy,R,{s:'var(--fig)',sw:1.4});
 [[0,'экватор 0°'],[23.44,'Северный тропик 23,5°'],[-23.44,'Южный тропик 23,5°'],[66.56,'Северный полярный круг 66,5°'],[-66.56,'Южный полярный круг 66,5°']].forEach(([l,t])=>{const x=R*Math.cos(l*Math.PI/180);s+=LN(cx-x,Y(l),cx+x+(l?0:0),Y(l),{c:l?'var(--accent-ink)':'var(--bad)',sw:l?1:1.6,dash:l?'4 3':null})+LN(cx+x,Y(l),190,Y(l),{sw:0.6,c:'var(--muted)'})+TX(193,Y(l)+4,t,{fs:9.5,a:'start'});});
 s+=TX(cx,cy+5,'жаркий',{fs:11,halo:2})+TX(cx,Y(45)+4,'умеренный',{fs:11,halo:2})+TX(cx,Y(-45)+4,'умеренный',{fs:11,halo:2})+TX(cx,Y(76)+4,'холодный',{fs:10,halo:2})+TX(cx,Y(-76)+4,'холодный',{fs:10,halo:2});
 return SV(340,222,s,'Пояса освещённости',340);})();
const figSolar=(()=>{let s='';const cy=60;const R=[6,9,11,8,26,22,15,15],D=[30,52,76,98,140,198,252,300];
 s+=CIR(-20,cy,40,{f:'var(--hl)'});PLANETS.forEach((p,i)=>{s+=CIR(D[i]+10,cy,R[i]/1.3,{f:i===2?WATER:i>=4?'var(--warn)':'var(--muted)',fo:0.8,s:'var(--fig)',sw:0.8})+TX(D[i]+10,cy+(i%2?-24:30),p[0],{fs:10,halo:2});if(i===5)s+=`<ellipse cx="${D[i]+10}" cy="${cy}" rx="24" ry="6" fill="none" stroke="var(--fig)" stroke-width="1.2"/>`;});
 return SV(340,104,s,'Солнечная система (не в масштабе)',340);})();

