G(7,()=>{const dl=pick([15,30,45,60,90,120,150]);const h=dl/15;
 return NUM(h,{q:`★ Земля поворачивается на 360° за 24 часа. На сколько часов отличается местное время двух городов, если между ними ${dl}° по долготе?`,short:`${dl} : 15 = ${h} ч.`,explain:`За 1 ч Земля поворачивается на ${M('360 : 24 = 15°')}. Значит, разница: ${M(`${dl} : 15 = ${h} ч`)}.`,explain2:'Каждые 15° долготы — 1 час разницы.'});},{star:true});
G(7,()=>{const a=pick(CITIES_T),b=pick(CITIES_T);if(a===b)return null;const t=pick([9,10,12,14,15]);const lt=t+(b[1]-a[1])/15;const lt2=((rnd(lt,1)%24)+24)%24;if(!Number.isInteger(lt2*2))return null;
 const hh=Math.floor(lt2),mm=Math.round((lt2-hh)*60);
 return CH(`★ В городе ${a[0]} (${N(Math.abs(a[1]))}° ${a[1]>=0?'в. д.':'з. д.'}) по местному солнечному времени ${t}:00. Сколько примерно местного солнечного времени в городе ${b[0]} (${N(Math.abs(b[1]))}° ${b[1]>=0?'в. д.':'з. д.'})?`,`${hh}:${String(mm).padStart(2,'0')}`,[`${(hh+2)%24}:${String(mm).padStart(2,'0')}`,`${(hh+22)%24}:${String(mm).padStart(2,'0')}`,`${((2*t-hh)%24+24)%24}:${String(mm).padStart(2,'0')}`],{
  short:`Разница ${N(rnd((b[1]-a[1])/15,2))} ч.`,explain:`Разница долгот: ${N(Math.abs(b[1]-a[1]))}°; ${M(`${N(Math.abs(b[1]-a[1]))} : 15 ≈ ${N(rnd(Math.abs(b[1]-a[1])/15,2))} ч`)}. ${b[1]>a[1]?'Город восточнее — время больше':'Город западнее — время меньше'}: ≈ <b>${hh}:${String(mm).padStart(2,'0')}</b> (с округлением).`,
  explain2:'Восточнее — прибавляй, западнее — вычитай по 1 часу на каждые 15°.'});},{star:true});
