/* ---------------- widgets ---------------- */
function onTheory(root){
 const w=root.querySelector('#w-orbit');
 if(w){w.innerHTML=`<b>🌍 Земля на орбите: двигай дату и широту</b>${SL('oD','Дата:',0,364,1,172)}${SL('oL','Широта:',-90,90,1,56)}<div id="oP" class="fig"></div><div id="oS" class="fig"></div><div id="oT" style="text-align:center;line-height:1.7"></div>`;
  const g=id=>w.querySelector('#'+id);const u=()=>{const d=+g('oD').value,phi=+g('oL').value;const dl=decl(d);g('oDo').textContent=dateOf(d);g('oLo').textContent=Math.abs(phi)+'° '+(phi>=0?'с. ш.':'ю. ш.');
   g('oP').innerHTML=figOrbit(d);g('oS').innerHTML=SV(340,226,figEarthSide(dl,phi,{cx:200,cy:108,R:84}),'Освещение Земли',340);
   const L=dayLen(phi,dl);const hN=90-Math.abs(phi-dl);const hh=Math.floor(L),mm=Math.round((L-hh)*60);
   g('oT').innerHTML=`Солнце в зените над широтой <b>${N(rnd(Math.abs(dl),1))}° ${dl>=0?'с.':'ю.'} ш.</b> · Северное полушарие: <b>${seasonN(d)}</b>, Южное: <b>${seasonS(d)}</b><br>На широте ${Math.abs(phi)}°: день <span class="out">${L>=23.99?'полярный день — 24 ч':L<=0.01?'полярная ночь — 0 ч':hh+' ч '+mm+' мин'}</span>, высота Солнца в полдень <span class="out">${hN>0?N(rnd(hN,1))+'°':'Солнце не восходит'}</span>`;};
  g('oD').oninput=u;g('oL').oninput=u;u();}
 const p=root.querySelector('#w-pole');
 if(p){p.innerHTML=`<b>🕐 Вращение Земли: двигай время по Лондону</b>${SL('pT','Время в Лондоне:',0,23,1,12)}<div id="pP" class="fig"></div><div id="pX" style="line-height:1.6;font-size:15px"></div>`;
  const g=id=>p.querySelector('#'+id);const u=()=>{const t=+g('pT').value;g('pTo').textContent=t+':00';g('pP').innerHTML=figPole(t);
   g('pX').innerHTML=CITIES_T.map(([n,lon])=>{const lt=((t+lon/15)%24+24)%24;const hh=Math.floor(lt),mm=Math.round((lt-hh)*60)%60;return `${n}: <b>${hh}:${String(mm).padStart(2,'0')}</b> ${lt>=6&&lt<18?'☀':'🌙'}`;}).join(' · ')+'<br><span class="small">Местное солнечное время: +1 ч на каждые 15° к востоку. Красные точки — там день.</span>';};
  g('pT').oninput=u;u();}
}

